import type { POI } from "./poi";

type Lang = "de" | "hu" | "ro" | "en";
type SettlementTheme =
  | "capital"
  | "historic"
  | "fortified"
  | "coastal"
  | "port"
  | "nature"
  | "industrial"
  | "university"
  | "sports"
  | "border"
  | "polder"
  | "island"
  | "flower"
  | "new-town"
  | "shopping"
  | "water"
  | "royal"
  | "market"
  | "tourism"
  | "fruit"
  | "cheese"
  | "seafood"
  | "suburb"
  | "events";

interface SettlementRow {
  id: string;
  parent: string;
  coords: [number, number];
  name: string;
  theme: SettlementTheme;
}

